import express from 'express';
import multer from 'multer';
import crypto from 'crypto';
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';
import { all,db,defaultAdminAbilities,hashPassword,json,legacyRank,mapLesson,mapProblem,now,one,publicBootstrap,publicUser,roadmapObject,run,uid,verifyPassword,getDbSession,setDbSession,deleteDbSession } from './db.js';

const here=path.dirname(fileURLToPath(import.meta.url));
const root=path.resolve(here,'..');
const isVercel=Boolean(process.env.VERCEL);
const uploadsDir=isVercel?path.join('/tmp','uploads'):path.join(here,'uploads');
const distDir=path.join(root,'dist');
const app=express();
const PORT=3000;
const sessions=new Map();

function getSession(token){if(!token)return null;const mem=sessions.get(token);if(mem)return mem;const dbS=getDbSession(token);if(dbS){sessions.set(token,dbS);return dbS;}return null}
function saveSession(token,userId){const s={userId,createdAt:Date.now()};sessions.set(token,s);try{setDbSession(token,userId,s.createdAt)}catch{}}
function removeSession(token){sessions.delete(token);try{deleteDbSession(token)}catch{}}

try{fs.mkdirSync(uploadsDir,{recursive:true});}catch{}
app.use(express.json({limit:'4mb'}));
app.use('/uploads',express.static(uploadsDir));
function abilityFor(req){if(req.path.startsWith('/api/admin/lessons'))return 'manage_lessons';if(req.path.startsWith('/api/admin/roadmap'))return 'manage_roadmap';if(req.path.startsWith('/api/admin/problem-submissions'))return 'review_problems';if(req.path.startsWith('/api/admin/contributions'))return 'review_contributions';if(req.path.startsWith('/api/admin/reviewer-tickets'))return 'review_contributions';if(req.path.startsWith('/api/admin/collections'))return 'manage_library';if(req.path.startsWith('/api/admin/problems'))return 'manage_library';if(req.path.startsWith('/api/admin/files'))return 'manage_files';return null}
const roles=(...allowed)=>(req,res,next)=>{if(req.method==='DELETE'&&req.user.role!=='owner')return res.status(403).json({error:'حذف محتوا فقط برای Headmaster مجاز است.'});if(!allowed.includes(req.user.role))return res.status(403).json({error:'این بخش برای نقش شما در دسترس نیست.'});const ability=abilityFor(req);if(req.user.role==='admin'&&ability&&!Boolean(json(req.user.abilities_json,{} )[ability]))return res.status(403).json({error:'این دسترسی برای حساب Admin شما فعال نیست.'});next()};
function decorateUser(user){return user?.reviewer?{...user,role:'reviewer'}:user}
function auth(req,res,next){const token=String(req.headers.authorization||'').replace(/^Bearer\s+/i,'');const session=getSession(token);const user=session&&one('SELECT * FROM users WHERE id=:id',{id:session.userId});if(!user)return res.status(401).json({error:'برای این کار باید وارد حساب شوید.'});req.user=decorateUser(user);req.token=token;next()}
function optionalAuth(req,_res,next){const token=String(req.headers.authorization||'').replace(/^Bearer\s+/i,'');const session=getSession(token);req.user=decorateUser(session?one('SELECT * FROM users WHERE id=:id',{id:session.userId}):null);next()}
function auditTarget(req){const m=req.path.match(/^\/api\/admin\/(lessons|problems|contributions|collections|users|problem-submissions|reviewer-tickets)\/([^/]+)/);if(!m)return null;const type=m[1],id=m[2];if(type==='lessons')return one('SELECT id,title,status FROM lessons WHERE id=:id',{id});if(type==='problems')return one('SELECT id,name AS title,status FROM problems WHERE id=:id',{id});if(type==='contributions')return one('SELECT c.id,c.kind,p.name AS problem_name,c.status FROM contributions c JOIN problems p ON p.id=c.problem_id WHERE c.id=:id',{id});if(type==='collections')return one('SELECT id,title,slug FROM problem_collections WHERE id=:id',{id});if(type==='users')return one('SELECT id,username,display_name AS title,role,reviewer FROM users WHERE id=:id',{id});if(type==='problem-submissions')return one('SELECT ps.id,p.name AS title,ps.status FROM problem_submissions ps JOIN problems p ON p.id=ps.problem_id WHERE ps.id=:id',{id});return one('SELECT id,subject AS title,status FROM reviewer_tickets WHERE id=:id',{id})}
function writeAudit(req,statusCode=200,summary='',before=null,response=null){if(!req.user)return;try{const safeBody=Object.fromEntries(Object.entries(req.body||{}).filter(([key])=>!['password','passwordHash','passwordSalt'].includes(key)));const metadata={before,target:before||null,request:safeBody,after:auditTarget(req),responseStatus:statusCode,response:response&&typeof response==='object'?{ok:response.ok,status:response.status,error:response.error}:null};run('INSERT INTO audit_logs (id,actor_id,actor_username,actor_role,method,path,status_code,summary,metadata_json,created_at) VALUES (:id,:actorId,:username,:role,:method,:path,:status,:summary,:metadata,:stamp)',{id:uid('audit'),actorId:req.user.id,username:req.user.username,role:req.user.role,method:req.method,path:req.originalUrl,status:statusCode,summary,metadata:JSON.stringify(metadata),stamp:now()})}catch{/* audit must never break a request */}}
app.use((req,res,next)=>{if(!req.path.startsWith('/api/')||req.method==='GET')return next();const before=auditTarget(req);const original=res.json.bind(res);res.json=(body)=>{const out=original(body);writeAudit(req,res.statusCode,req.method+' '+req.path,before,body);return out};next()});
app.put('/api/admin/problem-submissions/:id',auth,roles('owner','admin'),(req,res,next)=>{const sub=one(`SELECT ps.*,p.source_id,p.url_key FROM problem_submissions ps JOIN problems p ON p.id=ps.problem_id WHERE ps.id=:id`,{id:req.params.id});if(!sub)return res.status(404).json({error:'پیشنهاد مسئله پیدا نشد.'});if(sub.status!=='pending')return res.status(409).json({error:'این پیشنهاد قبلاً بررسی شده و دوباره قابل پردازش نیست.'});const status=req.body?.status;if(status==='rejected'){const stamp=now();run(`UPDATE problem_submissions SET status='rejected',review_note=:note,reviewed_at=:stamp WHERE id=:id`,{id:sub.id,note:String(req.body?.reviewNote||'توسط ادمین رد شد.'),stamp});run(`UPDATE problems SET status='draft',updated_at=:stamp WHERE id=:id`,{id:sub.problem_id,stamp});return res.json({ok:true,status})}if(status!=='accepted')return res.status(400).json({error:'وضعیت نامعتبر است.'});const urlKey=normalizeUrlKey(req.body?.urlKey||sub.url_key);if(!urlKey)return res.status(400).json({error:'برای انتشار، شناسه URL را وارد کنید.'});if(one('SELECT id FROM problems WHERE source_id=:sourceId AND url_key=:urlKey AND id<>:id',{sourceId:sub.source_id,urlKey,id:sub.problem_id}))return res.status(409).json({error:'این شناسه URL برای این منبع قبلاً استفاده شده است.'});let result;db.exec('BEGIN');try{result=publishSelectedSubmission(sub,req.user.id,{...req.body,urlKey});if(result.error){db.exec('ROLLBACK');return res.status(400).json({error:result.error})}db.exec('COMMIT')}catch(error){db.exec('ROLLBACK');return res.status(500).json({error:'انتشار مسئله انجام نشد.'})}res.json({ok:true,...result})});
app.get('/api/admin/logs',auth,roles('owner'),(_req,res)=>res.json(all('SELECT id,actor_username AS actorUsername,actor_role AS actorRole,method,path,status_code AS statusCode,summary,metadata_json AS metadataJson,created_at AS createdAt FROM audit_logs ORDER BY created_at DESC LIMIT 500')));
app.put('/api/admin/users/:id/abilities',auth,roles('owner'),(req,res)=>{const allowed=Object.keys(defaultAdminAbilities);const abilities=Object.fromEntries(allowed.map(key=>[key,Boolean(req.body?.abilities?.[key])]));run('UPDATE users SET abilities_json=:abilities,updated_at=:stamp WHERE id=:id',{id:req.params.id,abilities:JSON.stringify(abilities),stamp:now()});res.json(publicUser(one('SELECT * FROM users WHERE id=:id',{id:req.params.id})))});
app.put('/api/admin/users/:id/role',auth,roles('owner'),(req,res)=>{const next=req.body?.role;if(!['owner','admin','reviewer','user'].includes(next))return res.status(400).json({error:'نقش نامعتبر است.'});if(req.params.id===req.user.id)return res.status(400).json({error:'نقش Headmaster فعلی را نمی‌توان تغییر داد.'});if(next==='owner'&&one("SELECT id FROM users WHERE role='owner' AND id<>:id",{id:req.params.id}))return res.status(409).json({error:'فقط یک Headmaster می‌تواند در سایت وجود داشته باشد.'});const storedRole=next==='reviewer'?'admin':next;run('UPDATE users SET role=:role,reviewer=:reviewer,updated_at=:stamp WHERE id=:id',{id:req.params.id,role:storedRole,reviewer:next==='reviewer'?1:0,stamp:now()});res.json(publicUser(one('SELECT * FROM users WHERE id=:id',{id:req.params.id})))});
app.post('/api/admin/users',auth,roles('owner'),(req,res,next)=>{if(req.body?.role!=='reviewer')return next();const x=req.body||{},username=String(x.username||'').trim(),email=String(x.email||'').trim(),firstName=String(x.firstName||'').trim(),lastName=String(x.lastName||'').trim();if(username.length<3||String(x.password||'').length<6||!email||!firstName||!lastName)return res.status(400).json({error:'نام کاربری، ایمیل، نام، نام خانوادگی و رمز عبور معتبر الزامی هستند.'});if(one('SELECT id FROM users WHERE username=:username COLLATE NOCASE OR email=:email COLLATE NOCASE',{username,email}))return res.status(409).json({error:'این نام کاربری یا ایمیل قبلاً ثبت شده است.'});const pass=hashPassword(String(x.password||'')),stamp=now(),user={id:uid('user'),username,email,displayName:`${x.firstName||''} ${x.lastName||''}`.trim()||x.username,firstName:x.firstName||'',lastName:x.lastName||'',grade:x.grade||'',role:'admin',reviewer:1,...pass,createdAt:stamp};run(`INSERT INTO users (id,username,email,display_name,first_name,last_name,grade,role,reviewer,password_salt,password_hash,created_at,updated_at) VALUES (:id,:username,:email,:displayName,:firstName,:lastName,:grade,:role,:reviewer,:passwordSalt,:passwordHash,:createdAt,:createdAt)`,user);res.json(publicUser({...user,display_name:user.displayName,created_at:stamp}))});
app.get('/api/public/collections',optionalAuth,(_req,res)=>res.json(all(`SELECT pc.id,pc.slug,pc.title,pc.description,s.name AS source_name,COUNT(p.id) AS problem_count FROM problem_collections pc LEFT JOIN problem_sources s ON s.id=pc.source_id LEFT JOIN problem_collection_items pci ON pci.collection_id=pc.id LEFT JOIN problems p ON p.id=pci.problem_id AND p.status='published' GROUP BY pc.id ORDER BY pc.title`).map(x=>({id:x.id,slug:x.slug,title:x.title,description:x.description,sourceName:x.source_name||'',problemCount:Number(x.problem_count)}))));
app.get('/api/reactions',optionalAuth,(req,res)=>{const type=String(req.query.contentType||'').trim(),id=String(req.query.contentId||'').trim();if(!type||!id)return res.status(400).json({error:'محتوا مشخص نشده است.'});const counts=one(`SELECT COALESCE(SUM(value=1),0) AS likes,COALESCE(SUM(value=-1),0) AS dislikes FROM content_reactions WHERE content_type=:type AND content_id=:id`,{type,id});const userValue=req.user?one('SELECT value FROM content_reactions WHERE user_id=:userId AND content_type=:type AND content_id=:id',{userId:req.user.id,type,id})?.value||0:0;const visible=req.user&&['owner','admin'].includes(req.user.role);res.json({userValue,...(visible?{likes:Number(counts.likes),dislikes:Number(counts.dislikes)}:{})})});
app.post('/api/reactions',auth,(req,res)=>{const type=String(req.body?.contentType||'').trim(),id=String(req.body?.contentId||'').trim(),value=Number(req.body?.value);if(!type||!id||![1,-1].includes(value))return res.status(400).json({error:'واکنش نامعتبر است.'});const stamp=now();run(`INSERT INTO content_reactions (user_id,content_type,content_id,value,created_at,updated_at) VALUES (:userId,:type,:id,:value,:stamp,:stamp) ON CONFLICT(user_id,content_type,content_id) DO UPDATE SET value=excluded.value,updated_at=excluded.updated_at`,{userId:req.user.id,type,id,value,stamp});res.json({ok:true,value})});
app.get('/api/admin/collections',auth,roles('owner','admin'),(_req,res)=>res.json(all(`SELECT pc.id,pc.slug,pc.title,pc.description,pc.source_id,COUNT(pci.problem_id) AS problem_count FROM problem_collections pc LEFT JOIN problem_collection_items pci ON pci.collection_id=pc.id GROUP BY pc.id ORDER BY pc.title`).map(x=>({id:x.id,slug:x.slug,title:x.title,description:x.description,sourceId:x.source_id||'',problemCount:Number(x.problem_count)}))));
app.get('/api/admin/collections/:id',auth,roles('owner','admin'),(req,res)=>{const c=one('SELECT * FROM problem_collections WHERE id=:id',{id:req.params.id});if(!c)return res.status(404).json({error:'مجموعه پیدا نشد.'});res.json({...c,problemIds:all('SELECT problem_id FROM problem_collection_items WHERE collection_id=:id ORDER BY position',{id:c.id}).map(x=>x.problem_id)})});
app.post('/api/admin/collections',auth,roles('owner'),(req,res)=>{const x=req.body||{},title=String(x.title||'').trim(),slug=String(x.slug||title).toLowerCase().replace(/[^a-z0-9-]+/g,'-').replace(/^-|-$/g,'');if(!title||!slug)return res.status(400).json({error:'عنوان و شناسه مجموعه الزامی است.'});const id=uid('collection'),stamp=now();run(`INSERT INTO problem_collections (id,slug,title,description,source_id,created_by,created_at,updated_at) VALUES (:id,:slug,:title,:description,:sourceId,:userId,:stamp,:stamp)`,{id,slug,title,description:x.description||'',sourceId:x.sourceId||null,userId:req.user.id,stamp});res.json({id,slug,title,description:x.description||'',sourceId:x.sourceId||'',problemCount:0})});
app.put('/api/admin/collections/:id',auth,roles('owner','admin'),(req,res)=>{const c=one('SELECT * FROM problem_collections WHERE id=:id',{id:req.params.id});if(!c)return res.status(404).json({error:'مجموعه پیدا نشد.'});const ids=[...new Set((Array.isArray(req.body?.problemIds)?req.body.problemIds:[]).map(String))];db.exec('BEGIN');try{run('DELETE FROM problem_collection_items WHERE collection_id=:id',{id:c.id});ids.forEach((problemId,position)=>run('INSERT OR IGNORE INTO problem_collection_items (collection_id,problem_id,position) VALUES (:collectionId,:problemId,:position)',{collectionId:c.id,problemId,position}));run('UPDATE problem_collections SET title=:title,description=:description,source_id=:sourceId,updated_at=:stamp WHERE id=:id',{id:c.id,title:req.body?.title??c.title,description:req.body?.description??c.description,sourceId:req.body?.sourceId||c.source_id||null,stamp:now()});db.exec('COMMIT');res.json({ok:true,problemIds:ids})}catch(e){db.exec('ROLLBACK');res.status(400).json({error:e.message})}});
app.delete('/api/admin/collections/:id',auth,roles('owner'),(req,res)=>{run('DELETE FROM problem_collections WHERE id=:id',{id:req.params.id});res.json({ok:true})});
app.get('/api/admin/reviewer-tickets',auth,roles('owner','admin'),(_req,res)=>res.json(all(`SELECT t.*,u.username,u.display_name FROM reviewer_tickets t JOIN users u ON u.id=t.user_id ORDER BY CASE t.status WHEN 'open' THEN 0 WHEN 'in_progress' THEN 1 ELSE 2 END,t.created_at DESC`).map(x=>({id:x.id,username:x.username,displayName:x.display_name,subject:x.subject,body:x.body,status:x.status,adminNote:x.admin_note,createdAt:x.created_at}))));
app.put('/api/admin/reviewer-tickets/:id',auth,roles('owner','admin'),(req,res)=>{const status=['open','in_progress','closed'].includes(req.body?.status)?req.body.status:'closed';run('UPDATE reviewer_tickets SET status=:status,admin_note=:note,reviewed_by=:reviewer,reviewed_at=:stamp WHERE id=:id',{id:req.params.id,status,note:req.body?.adminNote||'',reviewer:req.user.id,stamp:now()});res.json({ok:true,status})});
function sourceProblemRows(){return all(`SELECT p.*,s.name AS source_name,s.slug AS source_slug,s.url AS source_url,s.brand_color FROM problems p JOIN problem_sources s ON s.id=p.source_id`)}
function authorLabel(id){const u=id&&one('SELECT username,role FROM users WHERE id=:id',{id});return !u||['owner','admin'].includes(u.role)?'CupHead':u.username}
function replaceNewlines(value=''){return String(value).replaceAll('\\n','\n')}
function normalizeUrlKey(value=''){return String(value||'').trim().replace(/\s+/g,'-').replace(/[^a-zA-Z0-9_-]/g,'-').replace(/-+/g,'-').replace(/^-|-$/g,'')}
const codeforcesTags=['2-sat','binary search','bitmasks','brute force','chinese remainder theorem','combinatorics','constructive algorithms','data structures','dfs and similar','divide and conquer','dp','dsu','expression parsing','fft','flows','games','geometry','graph matchings','graphs','greedy','hashing','implementation','interactive','math','matrices','meet-in-the-middle','number theory','probabilities','schedules','shortest paths','sortings','string suffix structures','strings','ternary search','trees','two pointers'];
function cleanTags(value){return [...new Set((Array.isArray(value)?value:[]).map(x=>String(x).trim()).filter(x=>codeforcesTags.includes(x)))].slice(0,8)}
function problemMeta(x,sourceId){const source=one('SELECT slug FROM problem_sources WHERE id=:id',{id:sourceId});const tags=cleanTags(x.tags);const rating=x.rating===''||x.rating===null||x.rating===undefined?null:Number(x.rating);if(!source)return {error:'منبع مسئله پیدا نشد.'};if(source.slug==='codeforces'&&rating!==null&&(!Number.isInteger(rating)||rating<0||rating%100!==0))return {error:'ریت Codeforces باید مضربی از ۱۰۰ باشد.'};return {source,tags,rating,topic:tags.join('، '),usacoLevel:String(x.usacoLevel||''),contestYear:x.contestYear?Number(x.contestYear):null,csesTopic:String(x.csesTopic||'')}}
function syncLessonRoadmap(lesson,previous=null){if(!lesson)return;const piece=lesson.piece||'pawn';const previousPiece=previous?.piece||previous?.rank;const moved=previous&&(previous.section!==lesson.section||previousPiece!==piece);if(lesson.status==='draft'||moved)all('SELECT id FROM roadmap_modules').forEach(mod=>run('DELETE FROM roadmap_module_lessons WHERE module_id=:moduleId AND lesson_id=:lessonId',{moduleId:mod.id,lessonId:lesson.id}));if(!['published','review'].includes(lesson.status))return;if(!moved&&one('SELECT module_id FROM roadmap_module_lessons WHERE lesson_id=:lessonId',{lessonId:lesson.id}))return;const modules=all('SELECT * FROM roadmap_modules WHERE section=:section AND piece=:piece ORDER BY position',{section:lesson.section,piece});let module=modules.at(-1);if(!module){const id=uid('mod');const position=one('SELECT COALESCE(MAX(position),-1)+1 AS next FROM roadmap_modules WHERE section=:section AND piece=:piece',{section:lesson.section,piece}).next;run(`INSERT INTO roadmap_modules (id,section,rank,piece,title,description,position) VALUES (:id,:section,:rank,:piece,:title,:description,:position)`,{id,section:lesson.section,rank:legacyRank(piece),piece,title:'درس‌های جدید',description:'درس‌های رسمی این مهره',position});module=one('SELECT * FROM roadmap_modules WHERE id=:id',{id})}const position=one('SELECT COALESCE(MAX(position),-1)+1 AS next FROM roadmap_module_lessons WHERE module_id=:moduleId',{moduleId:module.id}).next;run('INSERT OR IGNORE INTO roadmap_module_lessons (module_id,lesson_id,position) VALUES (:moduleId,:lessonId,:position)',{moduleId:module.id,lessonId:lesson.id,position})}
try{all("SELECT * FROM lessons WHERE status IN ('published','review')").forEach(l=>syncLessonRoadmap(l))}catch(e){console.warn('Roadmap lesson sync warning:',e.message)}
function saveLessonPractice(lessonId,items){run('DELETE FROM lesson_practice_items WHERE lesson_id=:lessonId',{lessonId});(Array.isArray(items)?items:[]).slice(0,100).forEach((item,position)=>{const name=String(item?.name||'').trim(),difficulty=String(item?.difficulty||'').trim(),url=String(item?.url||'').trim();if(!name&&!url)return;run('INSERT INTO lesson_practice_items (id,lesson_id,name,difficulty,url,position) VALUES (:id,:lessonId,:name,:difficulty,:url,:position)',{id:uid('practice'),lessonId,name,difficulty,url,position})})}
function detailByRow(p,userId){if(!p||p.status!=='published')return null;const item=mapProblem(p,userId);item.authorLabel=authorLabel(p.created_by);item.statements=all(`SELECT ps.id,ps.language,ps.content_markdown AS contentMarkdown,ps.input_markdown AS inputMarkdown,ps.output_markdown AS outputMarkdown,ps.author_id FROM problem_statements ps WHERE ps.problem_id=:id AND ps.status='published' ORDER BY CASE ps.language WHEN 'fa' THEN 0 ELSE 1 END`,{id:p.id}).map(x=>({...x,contentMarkdown:replaceNewlines(x.contentMarkdown),inputMarkdown:replaceNewlines(x.inputMarkdown),outputMarkdown:replaceNewlines(x.outputMarkdown),authorLabel:authorLabel(x.author_id)}));item.education=all(`SELECT pe.id,pe.kind,pe.layer,pe.language,pe.title,pe.content_markdown AS contentMarkdown,pe.author_id FROM problem_education pe WHERE pe.problem_id=:id AND pe.status='published' ORDER BY pe.kind,pe.layer`,{id:p.id}).map(x=>({...x,contentMarkdown:replaceNewlines(x.contentMarkdown),authorLabel:authorLabel(x.author_id)}));return item}
function adminDetailById(id){const p=one('SELECT p.*,s.name AS source_name,s.slug AS source_slug,s.url AS source_url,s.brand_color FROM problems p JOIN problem_sources s ON s.id=p.source_id WHERE p.id=:id',{id});if(!p)return null;const item=adminProblem(p);item.urlKey=p.url_key||'';item.authorLabel=authorLabel(p.created_by);item.statements=all(`SELECT ps.id,ps.language,ps.content_markdown AS contentMarkdown,ps.input_markdown AS inputMarkdown,ps.output_markdown AS outputMarkdown,ps.status,ps.author_id FROM problem_statements ps WHERE ps.problem_id=:id ORDER BY CASE ps.language WHEN 'fa' THEN 0 ELSE 1 END,ps.status`,{id}).map(x=>({...x,contentMarkdown:replaceNewlines(x.contentMarkdown),inputMarkdown:replaceNewlines(x.inputMarkdown),outputMarkdown:replaceNewlines(x.outputMarkdown),authorLabel:authorLabel(x.author_id)}));item.education=all(`SELECT pe.id,pe.kind,pe.layer,pe.language,pe.title,pe.content_markdown AS contentMarkdown,pe.status,pe.author_id FROM problem_education pe WHERE pe.problem_id=:id ORDER BY pe.kind,pe.layer,pe.status`,{id}).map(x=>({...x,contentMarkdown:replaceNewlines(x.contentMarkdown),authorLabel:authorLabel(x.author_id)}));return item}
function detail(slug,userId){return detailByRow(sourceProblemRows().find(x=>x.slug===slug),userId)}
function detailByIdentity(sourceIdentifier,urlKey,userId){const p=sourceProblemRows().find(x=>(x.source_slug===sourceIdentifier||x.source_id===sourceIdentifier)&&(x.url_key===urlKey||x.slug===urlKey));return detailByRow(p,userId)}
function writeContent(problemId,x,authorId,status='published'){const stamp=now();if(x.statementFa||x.inputFa||x.outputFa)run(`INSERT INTO problem_statements (id,problem_id,language,content_markdown,input_markdown,output_markdown,status,author_id,created_at,updated_at) VALUES (:id,:problemId,'fa',:content,:input,:output,:status,:authorId,:stamp,:stamp) ON CONFLICT(problem_id,language,status) DO UPDATE SET content_markdown=excluded.content_markdown,input_markdown=excluded.input_markdown,output_markdown=excluded.output_markdown,author_id=excluded.author_id,updated_at=excluded.updated_at`,{id:uid('statement'),problemId,content:x.statementFa||'',input:x.inputFa||'',output:x.outputFa||'',status,authorId,stamp});if(x.statementEn||x.inputEn||x.outputEn)run(`INSERT INTO problem_statements (id,problem_id,language,content_markdown,input_markdown,output_markdown,status,author_id,created_at,updated_at) VALUES (:id,:problemId,'en',:content,:input,:output,:status,:authorId,:stamp,:stamp) ON CONFLICT(problem_id,language,status) DO UPDATE SET content_markdown=excluded.content_markdown,input_markdown=excluded.input_markdown,output_markdown=excluded.output_markdown,author_id=excluded.author_id,updated_at=excluded.updated_at`,{id:uid('statement'),problemId,content:x.statementEn||'',input:x.inputEn||'',output:x.outputEn||'',status,authorId,stamp});if(Array.isArray(x.hints))x.hints.slice(0,5).forEach((h,i)=>{if(h.content)run(`INSERT INTO problem_education (id,problem_id,kind,layer,language,title,content_markdown,status,author_id,created_at,updated_at) VALUES (:id,:problemId,'hint',:layer,'fa',:title,:content,:status,:authorId,:stamp,:stamp)`,{id:uid('edu'),problemId,layer:i+1,title:h.title||`راهنمایی ${i+1}`,content:h.content,status,authorId,stamp})});if(x.solution)run(`INSERT INTO problem_education (id,problem_id,kind,layer,language,title,content_markdown,status,author_id,created_at,updated_at) VALUES (:id,:problemId,'solution',0,'fa','راه‌حل',:content,:status,:authorId,:stamp,:stamp)`,{id:uid('edu'),problemId,content:x.solution,status,authorId,stamp});if(x.takeaway)run(`INSERT INTO problem_education (id,problem_id,kind,layer,language,title,content_markdown,status,author_id,created_at,updated_at) VALUES (:id,:problemId,'takeaway',0,'fa','نکته‌ی اصلی',:content,:status,:authorId,:stamp,:stamp)`,{id:uid('edu'),problemId,content:x.takeaway,status,authorId,stamp})}
function replaceOfficialContent(problemId,x,authorId){const status=one('SELECT status FROM problems WHERE id=:id',{id:problemId})?.status==='review'?'review':'published';run("DELETE FROM problem_statements WHERE problem_id=:id AND status=:status",{id:problemId,status});run("DELETE FROM problem_education WHERE problem_id=:id AND status=:status",{id:problemId,status});writeContent(problemId,x,authorId,status)}
function promoteProblem(id){run(`UPDATE problem_statements SET status='published',updated_at=:stamp WHERE problem_id=:id AND status='review'`,{id,stamp:now()});run(`UPDATE problem_education SET status='published',updated_at=:stamp WHERE problem_id=:id AND status='review'`,{id,stamp:now()});const sub=one('SELECT * FROM problem_submissions WHERE problem_id=:id',{id});if(sub&&sub.status!=='accepted'){const xp=one("SELECT value FROM xp_settings WHERE key='problem'")?.value||100;run(`UPDATE problem_submissions SET status='accepted',xp_awarded=:xp,reviewed_at=:stamp WHERE id=:id`,{id:sub.id,xp,stamp:now()})}}
function publishSelectedSubmission(sub,reviewer,body){const requested=body.publish||{};const statements=all(`SELECT * FROM problem_statements WHERE problem_id=:id AND status='review' ORDER BY language`,{id:sub.problem_id});const education=all(`SELECT * FROM problem_education WHERE problem_id=:id AND status='review' ORDER BY kind,layer`,{id:sub.problem_id});const statementFa=requested.statementFa!==false&&statements.some(x=>x.language==='fa');const statementEn=requested.statementEn===true&&statements.some(x=>x.language==='en');const statementIds=new Set([...(statementFa?statements.filter(x=>x.language==='fa').map(x=>x.id):[]),...(statementEn?statements.filter(x=>x.language==='en').map(x=>x.id):[])]);const selectedEducation=education.filter(x=>{if(x.kind==='hint'){const ids=Array.isArray(requested.hints)?requested.hints.map(String):education.filter(y=>y.kind==='hint').map(y=>y.id);return ids.includes(x.id)}if(x.kind==='solution')return requested.solution!==false;if(x.kind==='takeaway')return requested.takeaway!==false;return false});if(!statementIds.size)return {error:'حداقل یکی از بسته‌های صورت مسئله را منتشر کنید.'};const stamp=now();run(`DELETE FROM problem_statements WHERE problem_id=:id AND status='published'`,{id:sub.problem_id});run(`DELETE FROM problem_education WHERE problem_id=:id AND status='published'`,{id:sub.problem_id});for(const row of statements)if(!statementIds.has(row.id))run(`UPDATE problem_statements SET status='rejected',updated_at=:stamp WHERE id=:id`,{id:row.id,stamp});for(const row of education)if(!selectedEducation.some(x=>x.id===row.id))run(`UPDATE problem_education SET status='rejected',updated_at=:stamp WHERE id=:id`,{id:row.id,stamp});for(const row of statements.filter(x=>statementIds.has(x.id)))run(`UPDATE problem_statements SET status='published',updated_at=:stamp WHERE id=:id`,{id:row.id,stamp});for(const row of selectedEducation)run(`UPDATE problem_education SET status='published',updated_at=:stamp WHERE id=:id`,{id:row.id,stamp});const examples=requested.examples!==false;const problemXp=Number(one("SELECT value FROM xp_settings WHERE key='problem'")?.value||100);const unit={statement:Number(one("SELECT value FROM xp_settings WHERE key='statement'")?.value||0),hint:Number(one("SELECT value FROM xp_settings WHERE key='hint'")?.value||0),solution:Number(one("SELECT value FROM xp_settings WHERE key='solution'")?.value||0),takeaway:Number(one("SELECT value FROM xp_settings WHERE key='takeaway'")?.value||0)};run(`UPDATE problems SET url_key=:urlKey,status='published',examples_json=CASE WHEN :examples=1 THEN examples_json ELSE '[]' END,updated_at=:stamp WHERE id=:id`,{id:sub.problem_id,urlKey:normalizeUrlKey(body.urlKey||sub.url_key),examples:examples?1:0,stamp});run(`DELETE FROM contributions WHERE problem_id=:problemId AND contributor_id=:userId AND status='pending'`,{problemId:sub.problem_id,userId:sub.user_id});let extra=statementEn?unit.statement:0;const publishedParts={statementFa,statementEn,hints:selectedEducation.filter(x=>x.kind==='hint').map(x=>x.id),solution:selectedEducation.some(x=>x.kind==='solution'),takeaway:selectedEducation.some(x=>x.kind==='takeaway'),examples};const addContribution=(row,kind,language,layer,xp)=>{const id=uid('contribution');run(`INSERT INTO contributions (id,problem_id,contributor_id,kind,language,layer,title,content_markdown,status,review_note,reviewed_by,xp_awarded,published_id,created_at,reviewed_at) VALUES (:id,:problemId,:userId,:kind,:language,:layer,:title,:content,'accepted',:note,:reviewer,:xp,:published,:stamp,:stamp)`,{id,problemId:sub.problem_id,userId:sub.user_id,kind,language,layer,title:row.title||'',content:row.content_markdown,note:body.reviewNote||'',reviewer,xp,published:row.id,stamp});};for(const row of statements.filter(x=>x.language==='en'&&statementIds.has(x.id))){addContribution(row,'translation','en',0,unit.statement)}for(const row of selectedEducation){const xp=unit[row.kind]||0;extra+=xp;addContribution(row,row.kind,'fa',row.layer,xp)}const removed=[];if(!statementFa)removed.push('صورت مسئله فارسی');if(!statementEn&&statements.some(x=>x.language==='en'))removed.push('صورت مسئله انگلیسی');for(const kind of ['hint','solution','takeaway'])if(education.some(x=>x.kind===kind)&&!selectedEducation.some(x=>x.kind===kind))removed.push(kind==='hint'?'راهنمایی‌ها':kind==='solution'?'راه‌حل':'نکته‌ی اصلی');const note=String(body.reviewNote||'').trim()||(removed.length?`بخش‌های حذف‌شده توسط ادمین: ${removed.join('، ')}. بقیه‌ی محتوا منتشر شد.`:'محتوا پس از بررسی منتشر شد.');const total=problemXp+extra;run(`UPDATE problem_submissions SET status='accepted',xp_awarded=:xp,review_note=:note,published_parts_json=:parts,reviewed_at=:stamp WHERE id=:id`,{id:sub.id,xp:total,note,parts:JSON.stringify(publishedParts),stamp});return {status:'accepted',xpAwarded:total,reviewNote:note,publishedParts}};
function adminProblem(row){return {...mapProblem(row),status:row.status,createdAt:row.created_at,updatedAt:row.updated_at,authorLabel:authorLabel(row.created_by)}}
function parseExamples(x){return Array.isArray(x.examples)?x.examples:[]}
function saveSourceMeta(problemId,meta){run('UPDATE problems SET usaco_level=:usacoLevel,contest_year=:contestYear,cses_topic=:csesTopic WHERE id=:id',{id:problemId,usacoLevel:meta.usacoLevel||'',contestYear:meta.contestYear,csesTopic:meta.csesTopic||''})}

app.get('/api/public/bootstrap',optionalAuth,(req,res)=>res.json(publicBootstrap(req.user?.id||null)));
app.get('/api/public/collections',(_req,res)=>res.json(all(`SELECT pc.id,pc.slug,pc.title,pc.description,s.name AS source_name,COUNT(pci.problem_id) AS problem_count FROM problem_collections pc LEFT JOIN problem_sources s ON s.id=pc.source_id LEFT JOIN problem_collection_items pci ON pci.collection_id=pc.id GROUP BY pc.id ORDER BY pc.title`).map(x=>({id:x.id,slug:x.slug,title:x.title,description:x.description,sourceName:x.source_name||'',problemCount:Number(x.problem_count)}))));
app.get('/api/public/collections/:slug',optionalAuth,(req,res)=>{const c=one(`SELECT pc.*,s.name AS source_name FROM problem_collections pc LEFT JOIN problem_sources s ON s.id=pc.source_id WHERE pc.slug=:slug`,{slug:req.params.slug});if(!c)return res.status(404).json({error:'مجموعه پیدا نشد.'});const problems=all(`SELECT p.*,s.name AS source_name,s.slug AS source_slug,s.url AS source_url,s.brand_color FROM problem_collection_items pci JOIN problems p ON p.id=pci.problem_id JOIN problem_sources s ON s.id=p.source_id WHERE pci.collection_id=:id AND p.status='published' ORDER BY pci.position,p.name`,{id:c.id}).map(x=>mapProblem(x,req.user?.id||null));res.json({id:c.id,slug:c.slug,title:c.title,description:c.description,sourceName:c.source_name||'',problems})});
app.get('/api/public/problems/legacy/:slug',optionalAuth,(req,res)=>{const item=detail(req.params.slug,req.user?.id||null);return item?res.json(item):res.status(404).json({error:'مسئله پیدا نشد.'})});
app.get('/api/public/problems/:source/:identifier',optionalAuth,(req,res)=>{const item=detailByIdentity(req.params.source,req.params.identifier,req.user?.id||null);return item?res.json(item):res.status(404).json({error:'مسئله پیدا نشد.'})});
app.get('/api/public/scoreboard',(_req,res)=>{const rows=all(`SELECT u.id,u.username,u.profile_image AS profileImage,COALESCE(SUM(CASE WHEN c.kind='translation' AND c.status='accepted' THEN 1 ELSE 0 END),0) statements,COALESCE(SUM(CASE WHEN c.kind='hint' AND c.status='accepted' THEN 1 ELSE 0 END),0) hints,COALESCE(SUM(CASE WHEN c.kind='solution' AND c.status='accepted' THEN 1 ELSE 0 END),0) solutions,COALESCE(SUM(CASE WHEN c.kind='takeaway' AND c.status='accepted' THEN 1 ELSE 0 END),0) takeaways,COALESCE((SELECT COUNT(*) FROM problem_submissions ps WHERE ps.user_id=u.id AND ps.status='accepted'),0) problems,COALESCE(SUM(CASE WHEN c.status='accepted' THEN c.xp_awarded ELSE 0 END),0)+COALESCE((SELECT SUM(ps.xp_awarded) FROM problem_submissions ps WHERE ps.user_id=u.id AND ps.status='accepted'),0) xp FROM users u LEFT JOIN contributions c ON c.contributor_id=u.id WHERE u.role='user' GROUP BY u.id ORDER BY xp DESC,username`).map(x=>({...x,statements:Number(x.statements),hints:Number(x.hints),solutions:Number(x.solutions),takeaways:Number(x.takeaways),problems:Number(x.problems),xp:Number(x.xp)}));res.json(rows)});
app.get('/api/public/xp-settings',(_req,res)=>res.json(Object.fromEntries(all('SELECT key,value FROM xp_settings').map(x=>[x.key,Number(x.value)]))));

app.post('/api/auth/register',(req,res)=>{const {username='',email='',firstName='',lastName='',grade='',password=''}=req.body||{};const validGrades=['پایه هفتم','پایه هشتم','پایه نهم','پایه دهم','پایه یازدهم','پایه دوازدهم','فارغ‌التحصیل'];if(String(username).trim().length<3||String(password).length<6||!String(email).trim()||!String(firstName).trim()||!String(lastName).trim()||!validGrades.includes(String(grade).trim()))return res.status(400).json({error:'ایمیل، نام، نام خانوادگی و پایه تحصیلی معتبر الزامی هستند.'});if(one('SELECT id FROM users WHERE username=:username OR email=:email',{username:String(username).trim(),email:String(email).trim()}))return res.status(409).json({error:'این نام کاربری یا ایمیل قبلاً ثبت شده است.'});const pass=hashPassword(String(password));const stamp=now();const user={id:uid('user'),username:String(username).trim(),email:String(email).trim(),displayName:`${firstName} ${lastName}`.trim(),firstName:String(firstName).trim(),lastName:String(lastName).trim(),grade:String(grade).trim(),role:'user',...pass,createdAt:stamp};run(`INSERT INTO users (id,username,email,display_name,first_name,last_name,grade,role,password_salt,password_hash,created_at,updated_at) VALUES (:id,:username,:email,:displayName,:firstName,:lastName,:grade,:role,:passwordSalt,:passwordHash,:createdAt,:createdAt)`,user);const token=crypto.randomBytes(32).toString('hex');saveSession(token,user.id);res.json({token,user:publicUser({...user,display_name:user.displayName,created_at:user.createdAt})})});
app.post(['/api/auth/login','/api/login'],(req,res)=>{const {username='',password=''}=req.body||{};const user=one('SELECT * FROM users WHERE username=:username COLLATE NOCASE OR email=:username COLLATE NOCASE',{username:String(username).trim()});if(!user||!verifyPassword(String(password),user))return res.status(401).json({error:'نام کاربری یا رمز عبور اشتباه است.'});const token=crypto.randomBytes(32).toString('hex');saveSession(token,user.id);res.json({token,user:publicUser(user)})});
app.get(['/api/auth/me','/api/me'],auth,(req,res)=>res.json({user:publicUser(req.user)}));app.post(['/api/auth/logout','/api/logout'],auth,(req,res)=>{removeSession(req.token);res.json({ok:true})});
app.get('/api/profile',auth,(req,res)=>{const solved=all('SELECT problem_id FROM progress WHERE user_id=:userId AND solved=1',{userId:req.user.id}).map(x=>x.problem_id);const contributions=all('SELECT id,kind,status,xp_awarded AS xpAwarded,created_at AS createdAt,review_note AS reviewNote FROM contributions WHERE contributor_id=:userId ORDER BY created_at DESC',{userId:req.user.id});const problemSubmissions=all(`SELECT ps.id,ps.problem_id,p.name AS problem_name,ps.status,ps.xp_awarded,ps.review_note,ps.published_parts_json,ps.created_at FROM problem_submissions ps JOIN problems p ON p.id=ps.problem_id WHERE ps.user_id=:userId ORDER BY ps.created_at DESC`,{userId:req.user.id}).map(x=>({id:x.id,problemId:x.problem_id,problemName:x.problem_name,status:x.status,xpAwarded:x.xp_awarded,reviewNote:x.review_note||'',publishedParts:json(x.published_parts_json,{}),createdAt:x.created_at}));const requests=all('SELECT id,status,motivation,experience,telegram_id AS telegramId,created_at AS createdAt FROM contributor_requests WHERE user_id=:userId ORDER BY created_at DESC',{userId:req.user.id});const tickets=all('SELECT id,subject,body,status,admin_note AS adminNote,created_at AS createdAt,reviewed_at AS reviewedAt FROM reviewer_tickets WHERE user_id=:userId ORDER BY created_at DESC',{userId:req.user.id});res.json({user:publicUser(req.user),solved,contributions,problemSubmissions,requests,tickets})});
app.post('/api/reviewer-tickets',auth,(req,res)=>{if(req.user.role!=='reviewer')return res.status(403).json({error:'ثبت تیکت فقط برای Reviewer مجاز است.'});const subject=String(req.body?.subject||'').trim(),body=String(req.body?.body||'').trim();if(!subject||!body)return res.status(400).json({error:'عنوان و متن تیکت الزامی هستند.'});const id=uid('ticket');run('INSERT INTO reviewer_tickets (id,user_id,subject,body,created_at) VALUES (:id,:userId,:subject,:body,:stamp)',{id,userId:req.user.id,subject,body,stamp:now()});res.json({id,status:'open'})});
app.put('/api/profile',auth,(req,res)=>{const x=req.body||{};const firstName=String(x.firstName??req.user.first_name).trim();const lastName=String(x.lastName??req.user.last_name).trim();const email=String(x.email??req.user.email).trim();const grade=String(x.grade??req.user.grade).trim();if(!firstName||!lastName||!email||!grade)return res.status(400).json({error:'ایمیل، نام، نام خانوادگی و پایه تحصیلی الزامی هستند.'});if(one('SELECT id FROM users WHERE email=:email COLLATE NOCASE AND id<>:id',{email,id:req.user.id}))return res.status(409).json({error:'این ایمیل قبلاً ثبت شده است.'});run(`UPDATE users SET display_name=:displayName,email=:email,first_name=:firstName,last_name=:lastName,grade=:grade,profile_image=COALESCE(:profileImage,profile_image),bio=COALESCE(:bio,bio),updated_at=:stamp WHERE id=:id`,{id:req.user.id,displayName:`${firstName} ${lastName}`,email,firstName,lastName,grade,profileImage:x.profileImage??null,bio:x.bio??null,stamp:now()});res.json({user:publicUser(one('SELECT * FROM users WHERE id=:id',{id:req.user.id}))})});
app.put('/api/progress/:problemId',auth,(req,res)=>{const solved=req.body?.solved?1:0;run(`INSERT INTO progress (user_id,problem_id,solved,updated_at) VALUES (:userId,:problemId,:solved,:stamp) ON CONFLICT(user_id,problem_id) DO UPDATE SET solved=excluded.solved,updated_at=excluded.updated_at`,{userId:req.user.id,problemId:req.params.problemId,solved,stamp:now()});res.json({solved:Boolean(solved)})});
app.post('/api/contributor-requests',auth,(req,res)=>{const {motivation='',experience='',telegramId=''}=req.body||{};if(req.user.role!=='user')return res.status(400).json({error:'حساب‌های رسمی CupHead نیازی به درخواست همکاری ندارند.'});if(!String(motivation).trim()||!String(telegramId).trim())return res.status(400).json({error:'زمینه‌ی همکاری و Telegram ID الزامی هستند.'});if(one(`SELECT id FROM contributor_requests WHERE user_id=:userId AND status IN ('pending','approved')`,{userId:req.user.id}))return res.status(409).json({error:'برای این حساب قبلاً درخواست همکاری ثبت شده است.'});const id=uid('request');run(`INSERT INTO contributor_requests (id,user_id,motivation,experience,telegram_id,created_at) VALUES (:id,:userId,:motivation,:experience,:telegramId,:stamp)`,{id,userId:req.user.id,motivation,experience,telegramId,stamp:now()});res.json({id,status:'pending'})});
app.post('/api/problems/:problemId/contributions',auth,(req,res)=>{const x=req.body||{};if(!['translation','hint','solution','takeaway'].includes(x.kind)||!String(x.contentMarkdown||'').trim())return res.status(400).json({error:'نوع و محتوای پیشنهاد را کامل کنید.'});if(!one("SELECT id FROM problems WHERE id=:id AND status='published'",{id:req.params.problemId}))return res.status(404).json({error:'مسئله پیدا نشد.'});const direct=['owner','admin'].includes(req.user.role);const status=direct?'accepted':'pending';const xpKey=x.kind==='translation'?'statement':x.kind;const xp=direct?0:Number(one('SELECT value FROM xp_settings WHERE key=:key',{key:xpKey})?.value||0);const language=x.kind==='translation'&&x.language==='en'?'en':'fa';const id=uid('contribution');run(`INSERT INTO contributions (id,problem_id,contributor_id,kind,language,layer,title,content_markdown,status,xp_awarded,created_at,reviewed_by,reviewed_at) VALUES (:id,:problemId,:userId,:kind,:language,:layer,:title,:content,:status,:xp,:stamp,:reviewedBy,:reviewedAt)`,{id,problemId:req.params.problemId,userId:req.user.id,kind:x.kind,language,layer:Number(x.layer)||0,title:x.title||'',content:x.contentMarkdown,status,xp,stamp:now(),reviewedBy:direct?req.user.id:null,reviewedAt:direct?now():null});if(direct){if(x.kind==='translation')writeContent(req.params.problemId,{statementFa:language==='fa'?x.contentMarkdown:'',statementEn:language==='en'?x.contentMarkdown:''},req.user.id);else writeContent(req.params.problemId,{hints:x.kind==='hint'?[{title:x.title,content:x.contentMarkdown}]:[],solution:x.kind==='solution'?x.contentMarkdown:'',takeaway:x.kind==='takeaway'?x.contentMarkdown:''},req.user.id);const published=one(x.kind==='translation'?'SELECT id FROM problem_statements WHERE problem_id=:problemId AND language=:language AND status=\'published\' ORDER BY updated_at DESC LIMIT 1':'SELECT id FROM problem_education WHERE problem_id=:problemId AND kind=:kind AND status=\'published\' ORDER BY updated_at DESC LIMIT 1',{problemId:req.params.problemId,language,kind:x.kind});if(published)run('UPDATE contributions SET published_id=:publishedId WHERE id=:id',{publishedId:published.id,id})}res.json({id,status})});
app.post('/api/problem-submissions',auth,(req,res)=>{if(['owner','admin','reviewer'].includes(req.user.role))return res.status(400).json({error:'حساب‌های رسمی باید از کتابخانه رسمی استفاده کنند.'});const x=req.body||{};if(!x.name||!x.link||!x.sourceId||!String(x.statementFa||'').trim())return res.status(400).json({error:'نام، منبع، لینک و صورت مسئله فارسی الزامی هستند.'});const meta=problemMeta(x,x.sourceId);if(meta.error)return res.status(400).json({error:meta.error});const id=uid('problem');const stamp=now();run(`INSERT INTO problems (id,slug,source_id,external_id,url_key,name,summary,topic,difficulty,rank,piece,rating,tags_json,examples_json,link,status,created_by,created_at,updated_at) VALUES (:id,:slug,:sourceId,:externalId,:urlKey,:name,:summary,:topic,:difficulty,:rank,:piece,:rating,:tags,:examples,:link,'review',:createdBy,:stamp,:stamp)`,{id,slug:x.slug||id,sourceId:x.sourceId,externalId:x.externalId||'',urlKey:normalizeUrlKey(x.urlKey),name:x.name,summary:'',topic:meta.topic,difficulty:x.difficulty||'متوسط',rank:legacyRank(x.rank||'pawn'),piece:x.rank||'pawn',rating:meta.rating,tags:JSON.stringify(meta.tags),examples:JSON.stringify(parseExamples(x)),link:x.link,createdBy:req.user.id,stamp});saveSourceMeta(id,meta);run(`INSERT INTO problem_submissions (id,problem_id,user_id,status,created_at) VALUES (:id,:problemId,:userId,'pending',:stamp)`,{id:uid('submission'),problemId:id,userId:req.user.id,stamp});writeContent(id,x,req.user.id,'review');res.json({problemId:id,status:'pending'})});
