async function startServer() {
  if (process.env.NODE_ENV !== 'production') {
    const { createServer: createViteServer } = await import('vite');
    const vite = await createViteServer({
      server: { middlewareMode: true },
      appType: 'spa',
    });
    app.use(vite.middlewares);
  } else if (fs.existsSync(distDir)) {
    app.use(express.static(distDir));
    app.get('*', (req, res, next) => {
      if (req.path.startsWith('/api/') || req.path.startsWith('/uploads/')) return next();
      res.sendFile(path.join(distDir, 'index.html'));
    });
  }
  app.listen(PORT, '0.0.0.0', () => console.log(`Cuphead running on http://0.0.0.0:${PORT}`));
}

const isDirectEntry = process.argv[1] && (process.argv[1].endsWith('server.js') || process.argv[1].endsWith('server.ts'));

if (!process.env.VERCEL && isDirectEntry) {
  startServer();
}

export default app;
export { app, startServer };
